import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Improving Ceph Economics with QAT Hardware Offload - Philip Williams, Canonical","description":"","frontmatter":{"title":"Improving Ceph Economics with QAT Hardware Offload - Philip Williams, Canonical","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","QAT","Storage Optimization","Intel","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Improving_Ceph_Economics_with_QAT_Hardware_Offload_-_Philip_Williams_Canonical.md","filePath":"posts/2025/Improving_Ceph_Economics_with_QAT_Hardware_Offload_-_Philip_Williams_Canonical.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Improving_Ceph_Economics_with_QAT_Hardware_Offload_-_Philip_Williams_Canonical.md"};function n(r,l,s,p,_,h){return a(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要-ceph与intel-qat技术的集成与优化" tabindex="-1">会议纪要：Ceph与Intel QAT技术的集成与优化 <a class="header-anchor" href="#会议纪要-ceph与intel-qat技术的集成与优化" aria-label="Permalink to &quot;会议纪要：Ceph与Intel QAT技术的集成与优化&quot;">​</a></h3><p><strong>会议主题</strong>：Ceph与Intel QAT（Quick Assist Technology）技术的集成与性能优化</p><p><strong>主讲人</strong>：pH Williams，Canonical产品经理</p><p><strong>会议时间</strong>：近期</p><h4 id="会议关键细节" tabindex="-1">会议关键细节： <a class="header-anchor" href="#会议关键细节" aria-label="Permalink to &quot;会议关键细节：&quot;">​</a></h4><ol><li><p><strong>Ceph与QAT的集成背景</strong>：</p><ul><li>Ceph作为硬件无关的分布式存储系统，通过集成Intel QAT硬件加速技术，可以提升性能和效率。</li><li>QAT支持加密、压缩等功能，特别适用于需要高性能存储和处理的场景。</li></ul></li><li><p><strong>QAT的历史与硬件支持</strong>：</p><ul><li>QAT技术最初作为PCIe卡于2008-2010年推出，后来集成到CPU中，如Intel的Ice Lake、Sapphire Rapids和Emerald Rapids处理器。</li></ul></li><li><p><strong>Ceph中的QAT应用</strong>：</p><ul><li>在RADOS Gateway (RGW)、BlueStore和OpenSSL等组件中启用QAT加速，提高压缩和加密效率。</li></ul></li><li><p><strong>性能测试与结果</strong>：</p><ul><li>在4节点Ceph集群上进行的性能测试显示，启用QAT压缩后，读取吞吐量恢复至接近无压缩水平，写入吞吐量略有提升。</li></ul></li><li><p><strong>不同数据集的压缩效果</strong>：</p><ul><li>对于合成数据，压缩后存储节省约25%；对于真实数据集，压缩效果各异，最高可达68%。</li></ul></li><li><p><strong>成本与收益分析</strong>：</p><ul><li>通过QAT压缩，可以在不显著增加成本的情况下，大幅减少存储空间需求，降低每GB存储的成本。</li></ul></li><li><p><strong>Ceph中的QAT启用步骤</strong>：</p><ul><li>使用MicroOS快速部署Ceph集群，启用QAT引擎服务，配置RADOS Gateway和Zone Placement，启用Zstandard（Zstd）压缩算法。</li></ul></li><li><p><strong>未来改进</strong>：</p><ul><li>Canonical正在改进snapd，以便更方便地与QAT引擎集成。</li></ul></li></ol><h4 id="讨论与决定事项" tabindex="-1">讨论与决定事项： <a class="header-anchor" href="#讨论与决定事项" aria-label="Permalink to &quot;讨论与决定事项：&quot;">​</a></h4><ul><li><strong>QAT在Ceph中的应用前景</strong>：QAT的压缩功能在Ceph中具有显著的商业价值。</li><li><strong>性能与成本的平衡</strong>：启用QAT会增加一定的CPU开销，但通过减少存储空间需求，可以在总体成本上获得显著收益。</li><li><strong>未来工作</strong>：Canonical将继续优化Ceph与QAT的集成。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><strong>进一步测试</strong>：在更多真实场景中测试QAT压缩的效果。</li><li><strong>文档更新</strong>：更新Ceph与QAT集成的文档。</li><li><strong>社区推广</strong>：向Ceph社区推广QAT的应用。</li></ol>',10)])])}const g=i(e,[["render",n]]);export{d as __pageData,g as default};
